    },
    {
      "card_ids": ["C06"],
      "claim": "L-4-fluorophenylglycine achieved brain/plasma ratios of 0.7–1.4 in rats and mice, indicating the 4-fluorophenyl motif is compatible with good brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Bicalutamide, which shares 4-fluorophenyl, nitrile, and CF3 groups, had poor brain penetration; however, its larger, more polar sulfone-containing structure makes it a weak counter-analogue for this smaller neutral molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
